def compute_tax_mv(quote, tax_bps):
    net = int(quote['net_cents'])
    tax = (net * int(tax_bps)) // 10000
    gross = net + tax
    return {
        'net_cents': net,
        'tax_cents': tax,
        'gross_cents': gross,
        'eur_clearing_delta_cents': tax + 30,
    }

